#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using LastRail.Auth;
using LastRail.Battle;
using LastRail.Run;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class RunWaveManifestTests {
  internal static JObject Source()=>JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/combat-b-wave-manifest-traces-20261003.json"));
  internal static JObject Packet(string name="signed-original-wave-manifest-from-actual-builder")=>(JObject)Source()["traces"].Single(x=>(string)x["name"]==name)["body"].DeepClone();
  internal static JObject Trust(JObject p){var original=Source()["originalStartSnapshot"];return new JObject{["accountId"]=original["bCombatPin"]["origin"]["accountId"].DeepClone(),["runId"]=original["runId"].DeepClone(),["startSnapshotHash"]=Packet()["startSnapshotHash"].DeepClone(),["parentPinHash"]=original["bCombatPin"]["pinHash"].DeepClone(),["manifestHash"]=original["bCombatPin"]["source"]["profile"]["definition"]["bWaveManifest"]["manifestHash"].DeepClone(),["packetHash"]=p["packetHash"].DeepClone(),["origin"]=original["bCombatPin"]["source"]["profile"]["definition"]["bWaveManifest"]["origin"].DeepClone(),["plan"]=original["admission"]["operationMapPlan"].DeepClone()};}
  static Type Model(){var type=typeof(RunApiHttpResponse).Assembly.GetType("LastRail.Run.RunWaveManifestSnapshot");Assert.NotNull(type,"Missing supplied wave manifest consumer");return type;}
  static object Read(JObject p,JObject trust=null)=>RunRiskBindingTests.Call(Model(),"Read",p,trust??Trust(p));
  [Test] public void ActualSupplierPacketIsImmutableMetadataWithSeparateTemplateAndInstanceSets(){var p=Packet();var snapshot=Read(p);Assert.IsTrue(JToken.DeepEquals(p,RunRiskBindingTests.Call(snapshot,"Capture") as JObject));p["manifest"]["templates"][0]["hp"]["value"]["numerator"]="999";Assert.AreEqual("17",(string)((JObject)RunRiskBindingTests.Call(snapshot,"Capture"))["manifest"]["templates"][0]["hp"]["value"]["numerator"]);Assert.AreEqual(2,((JArray)((JObject)RunRiskBindingTests.Call(snapshot,"Capture"))["manifest"]["waves"]).Count);}
  [Test] public void IndependentNativeContextCannotBeReplacedByRunIdentity(){var p=Packet();var trust=Trust(p);trust["origin"]["contextId"]=trust["runId"].DeepClone();Assert.Throws<ArgumentException>(()=>Read(p,trust));}
  static string Hash(JToken p)=>BDirectAttackInput.Digest(p).Substring(7);
  static void SelfHash(JObject p,string name){p.Remove(name);p[name]=Hash(p);}
  internal static JObject Rehash(JObject p){var m=(JObject)p["manifest"];if(m!=null){foreach(JObject t in (JArray)m["templates"])SelfHash(t,"templateHash");foreach(JObject w in (JArray)m["waves"])foreach(JObject i in (JArray)w["instances"]){var t=((JArray)m["templates"]).FirstOrDefault(x=>(string)x["templateId"]==(string)i["templateRef"]["templateId"]);if(t!=null)i["templateRef"]["templateHash"]=t["templateHash"].DeepClone();}SelfHash(m,"manifestHash");}SelfHash(p,"packetHash");return p;}
  static JObject SemanticTrust(JObject p){var t=Trust(p);t["manifestHash"]=p["manifest"]?["manifestHash"]?.DeepClone()??JValue.CreateNull();return t;}
  [TestCase("accountId")][TestCase("runId")][TestCase("startSnapshotHash")][TestCase("parentPinHash")][TestCase("manifestHash")][TestCase("packetHash")]
  public void AllExternalOwnerAndPinAnchorsAreRequired(string field){var p=Packet();var t=Trust(p);t[field]=field.EndsWith("Hash")?new string('f',64):"foreign";Assert.Throws<ArgumentException>(()=>Read(p,t));}
  [Test] public void TypedCollectionsAndOpaqueDefinitionAreDetached(){var s=(RunWaveManifestSnapshot)Read(Packet());Assert.AreEqual(2,s.Templates.Count);Assert.AreEqual(12,s.Waves.Sum(w=>w.Instances.Count));Assert.AreEqual("17",(string)s.Templates[0].Hp.Snapshot()["numerator"]);Assert.AreEqual("13",(string)s.Templates[0].Actions[0].Value.Snapshot()["numerator"]);s.Templates[0].CaptureDefinition()["purpose"]="altered";Assert.AreEqual("SCHEMA_TEST_ONLY_NO_GAME_PROFILE",(string)s.Templates[0].CaptureDefinition()["purpose"]);Assert.IsFalse(s.CanStart);Assert.IsFalse(s.FullCombatSupported);}
  [TestCase("support")][TestCase("context")][TestCase("risk")][TestCase("riskVersion")][TestCase("duplicateInstance")][TestCase("missingTemplate")][TestCase("templateVersion")][TestCase("sourceId129")][TestCase("duplicateAction")][TestCase("zeroHp")][TestCase("appliedFlag")][TestCase("entryOffset")][TestCase("entryGap")][TestCase("ordinal")][TestCase("nonCombatNode")][TestCase("extraRoot")][TestCase("extraInstance")]
  public void RehashedMalformedSemanticsCannotPassSelfHash(string fault){var p=Packet();var m=(JObject)p["manifest"];var t=(JObject)m["templates"][0];var w=(JObject)m["waves"][0];var i=(JObject)w["instances"][0];switch(fault){case "support":p["canStart"]=true;break;case "context":m["contextId"]=p["runId"].DeepClone();break;case "risk":m["origin"]["departure"]["selectedRisk"]="V";break;case "riskVersion":m["origin"]["riskApplicationVersion"]="old";break;case "duplicateInstance":m["waves"][1]["instances"][0]["instanceId"]=i["instanceId"].DeepClone();break;case "missingTemplate":i["templateRef"]["templateId"]="missing";break;case "templateVersion":i["templateRef"]["version"]="old";break;case "sourceId129":t["hp"]["sourceId"]=new string('a',129);break;case "duplicateAction":((JArray)t["actions"]).Add(t["actions"][0].DeepClone());break;case "zeroHp":t["hp"]["value"]["numerator"]="0";break;case "appliedFlag":t["actions"][0]["progressAppliedVersion"]="combat.b-operation-risk.v1.20261003";break;case "entryOffset":w["instances"][4]["entryNotBeforeMs"]=1799;break;case "entryGap":w["instances"][4]["entryGroup"]=2;break;case "ordinal":i["ordinal"]=1;break;case "nonCombatNode":w["nodeId"]="n1-1";break;case "extraRoot":p["newRngField"]=true;break;case "extraInstance":i["currentHp"]=17;break;}Rehash(p);Assert.Throws<ArgumentException>(()=>Read(p,SemanticTrust(p)));}
  [TestCase("templates",33)][TestCase("actions",33)][TestCase("waves",129)][TestCase("instances",17)]
  public void ExactCollectionLimitsRejectOverflowWithoutTruncation(string field,int count){var p=Packet();var m=(JObject)p["manifest"];var list=field=="templates"?(JArray)m["templates"]:field=="waves"?(JArray)m["waves"]:field=="actions"?(JArray)m["templates"][0]["actions"]:(JArray)m["waves"][0]["instances"];var first=list[0];while(list.Count<count)list.Add(first.DeepClone());Rehash(p);Assert.Throws<ArgumentException>(()=>Read(p,SemanticTrust(p)));}
  [Test] public void LargerThanOldApiReaderBudgetStillAcceptsValidBoundedManifest(){var p=Packet();p["manifest"]["templates"][0]["definition"]["padding"]=new string('a',300000);Rehash(p);var json=p.ToString();var s=RunWaveManifestSnapshot.ReadJson(json,SemanticTrust(p));Assert.AreEqual(300000,((string)s.Templates[0].CaptureDefinition()["padding"]).Length);}
  [Test] public void Utf8BudgetIsNotCharacterCount(){var p=Packet();p["manifest"]["templates"][0]["definition"]["padding"]=string.Concat(Enumerable.Repeat("한",180000));Rehash(p);Assert.Throws<ArgumentException>(()=>RunWaveManifestSnapshot.ReadJson(p.ToString(),SemanticTrust(p)));}
  [Test] public void HistoricalNullDoesNotCreateManifestOrDowngradeExpectedPin(){var p=Packet();p["manifest"]=JValue.CreateNull();p["manifestPinned"]=false;p["status"]="HISTORICAL_NO_MANIFEST";SelfHash(p,"packetHash");var expected=Trust(p);Assert.Throws<ArgumentException>(()=>Read(p,expected));var legacy=(JObject)expected.DeepClone();legacy["manifestHash"]=JValue.CreateNull();legacy["origin"]=JValue.CreateNull();legacy["plan"]=JValue.CreateNull();var s=(RunWaveManifestSnapshot)Read(p,legacy);Assert.IsFalse(s.HasManifest);Assert.AreEqual(0,s.Templates.Count);}
  [Test] public void JsonParserRejectsDuplicateFieldsCommentsTrailingValuesAndOldVersion(){var p=Packet();foreach(var json in new[]{p.ToString()+"{}",p.ToString().Insert(1,"\"version\":\"old\","),p.ToString().Insert(1,"/*comment*/")})Assert.Catch<Exception>(()=>RunWaveManifestSnapshot.ReadJson(json,Trust(p)));p["version"]="old";SelfHash(p,"packetHash");Assert.Throws<ArgumentException>(()=>Read(p));}
  internal static RunApiHttpResponse Response(JObject p)=>RunApiHttpResponse.Success(200,p.ToString(),new[]{new RunApiHttpHeader("Cache-Control","no-store"),new RunApiHttpHeader("ETag",(string)p["packetHash"])});
  static object Client(RunRiskBindingTests.Wire wire,Func<GameApiAuthSessionSnapshot> session,Func<long> generation){var type=typeof(RunApiHttpResponse).Assembly.GetType("LastRail.Run.RunWaveManifestClient");Assert.NotNull(type,"Missing authenticated manifest consumer");return Activator.CreateInstance(type,new object[]{new GameApiAuthenticatedHttpTransport(wire),session,generation});}
  static Task Refresh(object c,JObject t,string match=null,CancellationToken stop=default)=>(Task)RunRiskBindingTests.Call(c,"RefreshAsync",t,match,stop);
  static object Snapshot(object c)=>c.GetType().GetProperty("Snapshot").GetValue(c);
  [Test] public async Task OriginalBearerGetAtomicallyPublishesValidatedManifest(){var p=Packet();var wire=new RunRiskBindingTests.Wire{Reply=r=>Task.FromResult(Response(p))};var owner=RunRiskBindingTests.Session();using var c=(IDisposable)Client(wire,()=>owner,()=>1);await Refresh(c,Trust(p));Assert.NotNull(Snapshot(c));Assert.AreEqual("GET",wire.Last.Method);Assert.AreEqual("/v1/runs/"+(string)p["runId"]+"/b-wave-manifest",wire.Last.EndpointPath);Assert.IsNull(wire.Last.BodyJson);Assert.IsTrue(wire.Last.Headers.Any(h=>h.Name=="Authorization"&&h.Value=="Bearer lst1.fixture"));Assert.IsTrue(wire.Last.Headers.Any(h=>h.Name=="X-Combat-B-Wave-Manifest-Version"&&h.Value==RunWaveManifestSnapshot.Version));}
  [Test] public async Task FailedReadRetainsLastVerifiedSnapshotAndRestoreRejectsBeforeMutation(){var p=Packet();var owner=RunRiskBindingTests.Session();var wire=new RunRiskBindingTests.Wire{Reply=r=>Task.FromResult(Response(p))};using var c=new RunWaveManifestClient(new GameApiAuthenticatedHttpTransport(wire),()=>owner,()=>1);await c.RefreshAsync(Trust(p));var first=c.Snapshot;var bad=(JObject)p.DeepClone();bad["canStart"]=true;SelfHash(bad,"packetHash");wire.Reply=r=>Task.FromResult(Response(bad));await c.RefreshAsync(Trust(bad));Assert.AreSame(first,c.Snapshot);Assert.AreEqual("CONTRACT_MISMATCH",c.Status);Assert.Throws<ArgumentException>(()=>c.RestoreVerified(bad,Trust(bad)));Assert.AreSame(first,c.Snapshot);wire.Reply=r=>Task.FromResult(RunApiHttpResponse.Success(409,"{\"errorCode\":\"combat_b_wave_stale\"}"));await c.RefreshAsync(Trust(p));Assert.AreEqual("STALE",c.Status);Assert.AreSame(first,c.Snapshot);}
  [Test] public async Task RestoreSupersedesPendingResponseAndDisposeCancelsOnlyOwnedWait(){var p=Packet();var owner=RunRiskBindingTests.Session();var pending=new TaskCompletionSource<RunApiHttpResponse>();var wire=new RunRiskBindingTests.Wire{Reply=r=>pending.Task};var c=new RunWaveManifestClient(new GameApiAuthenticatedHttpTransport(wire),()=>owner,()=>1);var wait=c.RefreshAsync(Trust(p));c.RestoreVerified(p,Trust(p));Assert.AreSame(wait,await Task.WhenAny(wait,Task.Delay(200)));await wait;pending.SetResult(RunApiHttpResponse.Success(409,"{\"errorCode\":\"combat_b_wave_stale\"}"));Assert.AreEqual("READY",c.Status);Assert.IsTrue(JToken.DeepEquals(p,c.Snapshot.Capture()));pending=new TaskCompletionSource<RunApiHttpResponse>();wait=c.RefreshAsync(Trust(p));c.Dispose();Assert.AreSame(wait,await Task.WhenAny(wait,Task.Delay(200)));await wait;pending.SetResult(Response(p));Assert.IsNull(c.Snapshot);}
  [Test] public async Task ReplacedOwnerCannotPublishLateAndAuthRejectionClearsSnapshot(){var p=Packet();var owner=RunRiskBindingTests.Session();long generation=1;var wire=new RunRiskBindingTests.Wire{Reply=r=>Task.FromResult(Response(p))};using var c=new RunWaveManifestClient(new GameApiAuthenticatedHttpTransport(wire),()=>owner,()=>generation);await c.RefreshAsync(Trust(p));var pending=new TaskCompletionSource<RunApiHttpResponse>();wire.Reply=r=>pending.Task;var wait=c.RefreshAsync(Trust(p));generation++;owner=RunRiskBindingTests.Session();pending.SetResult(Response(p));await wait;Assert.IsNull(c.Snapshot);wire.Reply=r=>Task.FromResult(Response(p));await c.RefreshAsync(Trust(p));Assert.NotNull(c.Snapshot);wire.Reply=r=>Task.FromResult(RunApiHttpResponse.Success(401,"{\"errorCode\":\"auth_session_invalid\"}"));await c.RefreshAsync(Trust(p));Assert.IsNull(c.Snapshot);Assert.AreEqual("AUTH_REQUIRED",c.Status);}
  [Test] public async Task NewRunFailureCannotExposePreviousRun(){var p=Packet();var owner=RunRiskBindingTests.Session();var wire=new RunRiskBindingTests.Wire{Reply=r=>Task.FromResult(Response(p))};using var c=new RunWaveManifestClient(new GameApiAuthenticatedHttpTransport(wire),()=>owner,()=>1);await c.RefreshAsync(Trust(p));var t=Trust(p);t["runId"]="different-run";t["origin"]["departure"]["runId"]="different-run";wire.Reply=r=>Task.FromResult(RunApiHttpResponse.Success(409,"{\"errorCode\":\"combat_b_wave_stale\"}"));await c.RefreshAsync(t);Assert.IsNull(c.Snapshot);}
  [Test] public void ServerCanonicalOpaqueJsonGolden(){var type=typeof(RunWaveManifestSnapshot).Assembly.GetType("LastRail.Run.RunWaveManifestReader");var digest=type.GetMethod("Digest",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);var p=JObject.Parse("{\"2\":\"a\",\"10\":\"b\",\"fraction\":1e-7,\"integerFloat\":1.0}");Assert.AreEqual("a4b1057256376e3e58eea0c8dfd8c4de8a04e2ca9305067e0b0582f5b4e16357",digest.Invoke(null,new object[]{p}));}
  [Test] public void EcmaScriptNumberGoldensMatchSupplierBytes(){var type=typeof(RunWaveManifestSnapshot).Assembly.GetType("LastRail.Run.RunWaveManifestReader");var digest=type.GetMethod("Digest",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);foreach(JObject item in JArray.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CombatBMigration-20261003/WaveManifest/number-goldens.json")))Assert.AreEqual((string)item["sha256"],digest.Invoke(null,new object[]{((JObject)type.GetMethod("Parse",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{"{\"n\":"+(string)item["json"]+"}"}))["n"]}),(string)item["json"]);}
 }
}
